import{_ as t,o,c as n,ae as a}from"./chunks/framework.CSxHcPWC.js";const m=JSON.parse('{"title":"Welcome to Sentinel Engine","description":"","frontmatter":{},"headers":[],"relativePath":"introduction.md","filePath":"introduction.md"}'),r={name:"introduction.md"};function i(s,e,l,c,h,d){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="welcome-to-sentinel-engine" tabindex="-1">Welcome to Sentinel Engine <a class="header-anchor" href="#welcome-to-sentinel-engine" aria-label="Permalink to &quot;Welcome to Sentinel Engine&quot;">​</a></h1><p>Sentinel Engine represents a paradigm shift in threat protection. It balances ruthless security against automated vectors alongside an entirely frictionless experience for legitimate human users.</p><h2 id="the-architecture" tabindex="-1">The Architecture <a class="header-anchor" href="#the-architecture" aria-label="Permalink to &quot;The Architecture&quot;">​</a></h2><p>Our engine is deliberately split into two modules to satisfy different threat models:</p><ol><li><strong>V1 (The Shield):</strong> A synchronous, brutal firewall. Ideal for monolithic platforms where Zero-Trust is paramount and VPNs/Proxies must be heavily restricted immediately.</li><li><strong>V2 (The B2B Policy Engine):</strong> A hyper-fast (&lt;5ms) edge evaluator. It delegates border control to the <strong>Tenant</strong>. Bots, proxies, and networks are mathematically scored and optionally allowed, challenged, or blocked based on Custom DSL Rules configured by your clients.</li></ol><h2 id="the-secret-weapon" tabindex="-1">The Secret Weapon <a class="header-anchor" href="#the-secret-weapon" aria-label="Permalink to &quot;The Secret Weapon&quot;">​</a></h2><p>Sentinel doesn&#39;t use picture captchas. We use a <strong>Behavioral Work Token (BWT)</strong>. Instead of making users click crosswalks, we present a beautiful overlay instructing them to &quot;Click and hold to verify&quot;. While holding, their browser computes complex SHA256 hashes. It burns bot CPU and verifies human micro-interactions simultaneously.</p>',7)])])}const p=t(r,[["render",i]]);export{m as __pageData,p as default};
